type agreementNativeCodePayloadSite struct {
	Root, Node, Parent int
	Kind, ParentKind   string
	Lines, Text        []text.Segment
	Info               text.Segment
	HasInfo, Raw       bool
}

// Every code declaration retains its native container and complete segments,
// including empty fences and code inside an unused definition.
func agreementNativeCodePayloadSites(body string) []agreementNativeCodePayloadSite {
	ctx := parser.NewContext()
	ctx.Set(agreementFootnoteTargetsKey, make(map[string]int))
	var unused []*extast.Footnote
	ctx.Set(agreementUnusedFootnoteNodesKey, &unused)
	ctx.Set(agreementNativeDefinitionSpansKey, make(map[ast.Node]agreementNativeDefinitionSpan))
	doc := agreementNativeOwnerGrammar.Parser().Parse(text.NewReader([]byte(body)), parser.WithContext(ctx))
	roots := []ast.Node{doc}
	for _, n := range unused {
		roots = append(roots, n)
	}
	var sites []agreementNativeCodePayloadSite
	for ri, root := range roots {
		at := 0
		var parents []int
		if err := ast.Walk(root, func(n ast.Node, entering bool) (ast.WalkStatus, error) {
			if !entering {
				parents = parents[:len(parents)-1]
				return ast.WalkContinue, nil
			}
			parent := -1
			if len(parents) > 0 {
				parent = parents[len(parents)-1]
			}
			current := at
			at++
			parents = append(parents, current)
			site := agreementNativeCodePayloadSite{Root: ri, Node: current, Parent: parent, Kind: n.Kind().String(), Raw: n.IsRaw()}
			if n.Parent() != nil {
				site.ParentKind = n.Parent().Kind().String()
			}
			switch h := n.(type) {
			case *ast.CodeSpan:
				for child := h.FirstChild(); child != nil; child = child.NextSibling() {
					word, ok := child.(*ast.Text)
					if !ok {
						panic("native code span child is not text")
					}
					site.Text = append(site.Text, word.Segment)
				}
			case *ast.CodeBlock:
				for i := range h.Lines().Len() {
					site.Lines = append(site.Lines, h.Lines().At(i))
				}
			case *ast.FencedCodeBlock:
				for i := range h.Lines().Len() {
					site.Lines = append(site.Lines, h.Lines().At(i))
				}
				if h.Info != nil {
					site.Info, site.HasInfo = h.Info.Segment, true
				}
			default:
				return ast.WalkContinue, nil
			}
			sites = append(sites, site)
			return ast.WalkContinue, nil
		}); err != nil {
			panic(err)
		}
	}
	return sites
}

type agreementNativeCodePayloadTarget struct {
	Window   int
	Span     graph.Span
	Old, New string
}

// A private byte is absent from the whole authored body. Replace targets only
// inside native code spans, preserving every delimiter and byte position.
func agreementNativeCodePayloadRename(body string, windows []agreementNativeCodeWindow) (string, []agreementNativeCodePayloadTarget, bool) {
	if strings.Contains(body, "q") {
		return "", nil, false
	}
	private := []byte(body)
	var changes []agreementNativeCodePayloadTarget
	for wi, window := range windows {
		if window.Kind != "CodeSpan" {
			continue
		}
		if window.Span.Start < 0 || window.Span.Stop > len(body) || window.Span.Start >= window.Span.Stop {
			return "", nil, false
		}
		for offset := window.Span.Start; offset < window.Span.Stop; {
			relative := strings.Index(body[offset:window.Span.Stop], "[[")
			if relative < 0 {
				break
			}
			open := offset + relative
			closeAt := strings.Index(body[open+2:window.Span.Stop], "]]")
			if closeAt < 0 {
				return "", nil, false
			}
			end := open + 2 + closeAt + 2
			offset = end
			inner := body[open+2 : end-2]
			link, ok := graph.ParseWikilink(inner)
			if !ok || strings.ContainsAny(inner, "[]\r\n`") || link.Target == "" {
				return "", nil, false
			}
			start := open + 2 + strings.Index(inner, link.Target)
			stop := start + len(link.Target)
			if start < open+2 || stop > end-2 || body[start:stop] != link.Target {
				return "", nil, false
			}
			name := strings.Repeat("q", len(link.Target))
			copy(private[start:stop], name)
			changes = append(changes, agreementNativeCodePayloadTarget{Window: wi, Span: graph.Span{Start: start, Stop: stop}, Old: link.Target, New: name})
		}
	}
	return string(private), changes, len(changes) > 0
}

// The entire page code set is frozen separately. Every carrier must still
// occupy its native code span's exact authored text, including repeated fields.
func agreementNativeCodePayloadOwners(windows []agreementNativeCodeWindow, parts [][]agreementCodePart) (map[agreementCitation]int, bool) {
	if len(windows) != len(parts) {
		return nil, false
	}
	owners := make(map[agreementCitation]int)
	for i, window := range windows {
		fields := false
		for _, part := range parts[i] {
			fields = fields || part.Field
		}
		if !fields {
			continue
		}
		if window.Kind != "CodeSpan" {
			return nil, false
		}
		matched, valid := agreementMatchCodeWindow(window.Text, parts[i])
		if !valid {
			return nil, false
		}
		for tuple, count := range matched {
			owners[tuple] += count
		}
	}
	return owners, len(owners) > 0
}

